    "CREATE TRIGGER trg_framework_element_parent_same_version_insert\nBEFORE INSERT ON official_framework_element\nFOR EACH ROW\nWHEN NEW.parent_element_id IS NOT NULL\n AND (SELECT framework_version_id FROM official_framework_element WHERE id = NEW.parent_element_id) <> NEW.framework_version_id\nBEGIN\n    SELECT RAISE(ABORT, 'framework element parent must belong to same framework version');\nEND",
    "CREATE TRIGGER trg_framework_element_parent_same_version_update\nBEFORE UPDATE OF parent_element_id, framework_version_id ON official_framework_element\nFOR EACH ROW\nWHEN NEW.parent_element_id IS NOT NULL\n AND (SELECT framework_version_id FROM official_framework_element WHERE id = NEW.parent_element_id) <> NEW.framework_version_id\nBEGIN\n    SELECT RAISE(ABORT, 'framework element parent must belong to same framework version');\nEND",
    "CREATE TRIGGER trg_official_attachment_requires_official_origin\nBEFORE INSERT ON institutional_attachment\nFOR EACH ROW\nWHEN NEW.attachment_type = 'EXPLICIT' AND NEW.origin_type <> 'OFFICIAL'\nBEGIN\n    SELECT RAISE(ABORT, 'explicit institutional attachment must have OFFICIAL origin');\nEND",
    "CREATE TRIGGER trg_pedagogical_relation_reflexive_guard\nBEFORE INSERT ON pedagogical_relation\nFOR EACH ROW\nWHEN NEW.source_notion_id = NEW.target_notion_id\n AND COALESCE((SELECT allows_reflexive FROM pedagogical_relation_type WHERE code = NEW.relation_type_code), 0) = 0\nBEGIN\n    SELECT RAISE(ABORT, 'pedagogical relation type does not allow reflexive relation');\nEND",
    "CREATE TRIGGER trg_previous_resource_version_same_resource_insert\nBEFORE INSERT ON resource_version\nFOR EACH ROW\nWHEN NEW.previous_version_id IS NOT NULL\n AND (SELECT resource_id FROM resource_version WHERE id = NEW.previous_version_id) <> NEW.resource_id\nBEGIN\n    SELECT RAISE(ABORT, 'previous resource version must belong to same resource');\nEND",
    "CREATE TRIGGER trg_previous_resource_version_same_resource_update\nBEFORE UPDATE OF previous_version_id, resource_id ON resource_version\nFOR EACH ROW\nWHEN NEW.previous_version_id IS NOT NULL\n AND (SELECT resource_id FROM resource_version WHERE id = NEW.previous_version_id) <> NEW.resource_id\nBEGIN\n    SELECT RAISE(ABORT, 'previous resource version must belong to same resource');\nEND",
    "CREATE TRIGGER trg_resource_version_immutable_business_fields\nBEFORE UPDATE ON resource_version\nFOR EACH ROW\nWHEN OLD.lifecycle_status IN ('VALIDATED','PUBLISHED','ARCHIVED') AND (\n       COALESCE(NEW.title,'') <> COALESCE(OLD.title,'')\n    OR COALESCE(NEW.summary,'') <> COALESCE(OLD.summary,'')\n    OR COALESCE(NEW.body,'') <> COALESCE(OLD.body,'')\n    OR COALESCE(NEW.resource_id,'') <> COALESCE(OLD.resource_id,'')\n)\nBEGIN\n    SELECT RAISE(ABORT, 'validated/published/archived resource version is immutable on business content');\nEND",
    "CREATE VIEW v_current_resource_version AS\nSELECT rv.*\nFROM resource_version rv\nWHERE rv.lifecycle_status = 'PUBLISHED'\n  AND (rv.valid_from IS NULL OR rv.valid_from <= CURRENT_TIMESTAMP)\n  AND (rv.valid_to IS NULL OR rv.valid_to > CURRENT_TIMESTAMP)\n  AND NOT EXISTS (\n      SELECT 1\n      FROM resource_version newer\n      WHERE newer.resource_id = rv.resource_id\n        AND newer.lifecycle_status = 'PUBLISHED'\n        AND newer.created_at > rv.created_at\n        AND (newer.valid_from IS NULL OR newer.valid_from <= CURRENT_TIMESTAMP)\n        AND (newer.valid_to IS NULL OR newer.valid_to > CURRENT_TIMESTAMP)\n  )",
